PRAGMA foreign_keys=ON;
CREATE TABLE fixture_authorization(fixture_id TEXT PRIMARY KEY,token_hash TEXT NOT NULL);
CREATE TABLE source_concept(concept_id TEXT PRIMARY KEY,source_system TEXT NOT NULL,source_record_type TEXT NOT NULL,source_record_id TEXT NOT NULL,referent_key TEXT NOT NULL,concept_type TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(source_system,source_record_type,source_record_id,referent_key));
CREATE TABLE source_concept_revision(revision_id TEXT PRIMARY KEY,concept_id TEXT NOT NULL REFERENCES source_concept,source_revision TEXT NOT NULL,source_payload_hash TEXT NOT NULL,evidence_hash TEXT NOT NULL,source_timestamp TEXT,recorded_at TEXT NOT NULL,evidence_json TEXT NOT NULL,UNIQUE(concept_id,source_revision,source_payload_hash,evidence_hash),UNIQUE(concept_id,revision_id));
CREATE TABLE source_concept_head(concept_id TEXT PRIMARY KEY REFERENCES source_concept,revision_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('VALIDATED','UNRESOLVED','REVIEW_REQUIRED')),FOREIGN KEY(concept_id,revision_id) REFERENCES source_concept_revision(concept_id,revision_id));
CREATE TABLE concept_resolution_event(event_id TEXT PRIMARY KEY,concept_id TEXT NOT NULL REFERENCES source_concept,source_revision_id TEXT NOT NULL,candidate_substance_id TEXT,matching_status TEXT NOT NULL,admission_status TEXT NOT NULL,operation TEXT NOT NULL,outcome TEXT NOT NULL,evidence_digest TEXT NOT NULL,matcher_version TEXT NOT NULL,policy_version TEXT NOT NULL,registry_snapshot TEXT NOT NULL,previous_association_id TEXT,timestamp TEXT NOT NULL,reason_codes TEXT NOT NULL,decision_json TEXT NOT NULL,FOREIGN KEY(concept_id,source_revision_id) REFERENCES source_concept_revision(concept_id,revision_id));
CREATE TABLE concept_substance_association(association_id TEXT PRIMARY KEY,concept_id TEXT NOT NULL REFERENCES source_concept,substance_id TEXT NOT NULL REFERENCES substance_identity,association_type TEXT NOT NULL CHECK(association_type='EXACT'),association_status TEXT NOT NULL CHECK(association_status IN ('ACTIVE','REVIEW_REQUIRED','SUPERSEDED','REVOKED')),source_revision_id TEXT NOT NULL,validated_revision_id TEXT NOT NULL,resolution_event_id TEXT NOT NULL REFERENCES concept_resolution_event,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(concept_id,source_revision_id) REFERENCES source_concept_revision(concept_id,revision_id),FOREIGN KEY(concept_id,validated_revision_id) REFERENCES source_concept_revision(concept_id,revision_id));
CREATE UNIQUE INDEX one_reserved_exact ON concept_substance_association(concept_id) WHERE association_status IN ('ACTIVE','REVIEW_REQUIRED');
CREATE TABLE association_request(idempotency_key TEXT PRIMARY KEY,request_digest TEXT NOT NULL,concept_id TEXT NOT NULL REFERENCES source_concept,revision_id TEXT NOT NULL REFERENCES source_concept_revision,event_id TEXT NOT NULL REFERENCES concept_resolution_event,result_json TEXT NOT NULL);
CREATE VIEW current_exact_association AS SELECT a.* FROM concept_substance_association a JOIN source_concept_head h ON h.concept_id=a.concept_id AND h.revision_id=a.validated_revision_id WHERE a.association_status='ACTIVE' AND h.state='VALIDATED';
CREATE TRIGGER immutable_event_update BEFORE UPDATE ON concept_resolution_event BEGIN SELECT RAISE(ABORT,'APPEND_ONLY_EVENT'); END;
CREATE TRIGGER immutable_event_delete BEFORE DELETE ON concept_resolution_event BEGIN SELECT RAISE(ABORT,'APPEND_ONLY_EVENT'); END;
CREATE TRIGGER immutable_revision_update BEFORE UPDATE ON source_concept_revision BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REVISION'); END;
CREATE TRIGGER immutable_revision_delete BEFORE DELETE ON source_concept_revision BEGIN SELECT RAISE(ABORT,'IMMUTABLE_REVISION'); END;
CREATE TRIGGER immutable_concept_update BEFORE UPDATE ON source_concept BEGIN SELECT RAISE(ABORT,'IMMUTABLE_SOURCE_KEY'); END;
CREATE TRIGGER immutable_association_target BEFORE UPDATE OF concept_id,substance_id,source_revision_id ON concept_substance_association BEGIN SELECT RAISE(ABORT,'NO_REASSIGNMENT_V1'); END;
CREATE TRIGGER preserve_association BEFORE DELETE ON concept_substance_association BEGIN SELECT RAISE(ABORT,'PRESERVE_ASSOCIATION_HISTORY'); END;
